/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#11): the HTTP routes that a node registers on the app of the nodes (httpNode)
 *   with node.registerHttpRoute, tracked per instance of the node and removed when the
 *   runtime stops the node; the one place that reads the router of the app to remove them
 *   #82: ownerOf(route) - the node that registered a route (internal, for the record of a drain 503)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The HTTP routes of the nodes (#11).
 *
 * A node registers a route with `node.registerHttpRoute(method, path, ...handlers)`
 * (runtime/lib/nodes/Node.js). The route is an ordinary top-level layer of the app
 * of the nodes (`RED.httpNode`), created with the public `app.route(path)[method]()`
 * at the moment of the call - the same layer, at the same place, as
 * `RED.httpNode[method](path, ...handlers)` would create. Nothing is added to the
 * app: no middleware, no CORS, no parsing of cookies or bodies; `httpNodeAuth`
 * applies as to every route of the app.
 *
 * The routes are kept per instance of the node (not per id: an old and a new
 * instance share the id) and removed:
 *  - by `removeAll(node)`, called at the start of `Node.prototype.close` and in
 *    `Flow.stopNode` before the node is closed (a node that overrides `close`);
 *  - by `remove()` of the handle that the registration returned.
 * A route is removed in place from the current stack of the router, by the
 * identity of its `Route` object: a request that is not matched yet does not
 * reach it any more, a request that is already in it ends normally.
 *
 * After the runtime started to close the instance, a registration adds no route,
 * returns a handle whose `remove()` does nothing and logs one warning for the
 * instance. A failure to remove the routes is logged and does not stop the close;
 * the routes that were not removed stay tracked, so a later close or remove()
 * tries again.
 *
 * This module is a leaf: it requires only @node-red/util. The app is given by
 * `init(app)`; the router is read only by `routerStack(app)` (Express 4 and 5).
 */

const { log } = require("@node-red/util");

const METHODS = ["get", "post", "put", "patch", "delete", "options", "head", "all"];
const MAX_MESSAGE_LENGTH = 200;
const UNKNOWN_ERROR = "unknown error";

/** The app of the nodes given by the last init (null: none) */
let nodeApp = null;

/**
 * The state of an instance of a node:
 *  - `closed`: the runtime started to close the instance
 *  - `warned`: the warning of a registration after the close was logged
 *  - `routes`: the registrations that are still in place, `{app, route}`
 * A node that never registered a route and is not closed has no state.
 */
const states = new WeakMap();

/**
 * The node of each `Route` that `register()` created (#82): read by `ownerOf(route)`.
 * Keyed by the `Route` object (identity), so an entry lives only as long as the route
 * and a removal of the route does not forget its node.
 */
const owners = new WeakMap();

/**
 * Set the app on which the routes of the nodes are registered.
 * The routes registered before stay on the app they were registered on and are
 * removed from it.
 * @param {object} app the app of the nodes (`runtime.nodeApp`); without it a
 *                     registration throws
 */
function init(app) {
    nodeApp = app || null;
}

/**
 * The stack of the router of an app, read now: `app._router` (Express 4),
 * otherwise `app.router` (Express 5).
 * @param {object} app
 * @return {Array|null} the stack, or null when the app has no router or its
 *                      stack is not an array (nothing to remove)
 */
function routerStack(app) {
    let router = app._router;
    if (!router) {
        try {
            router = app.router;
        } catch (err) {
            // Express 4: `app.router` is a getter that throws (deprecated); it has no
            // router when `_router` is not set, so there is nothing to remove
            router = null;
        }
    }
    if (!router) {
        return null;
    }
    const stack = router.stack;
    return Array.isArray(stack) ? stack : null;
}

function typeError(text) {
    return new TypeError("registerHttpRoute: " + text);
}

/**
 * @return {string} the method in lower case
 */
function checkMethod(method) {
    // only a primitive string: nothing is called on another value
    if (typeof method !== "string") {
        throw typeError("the method must be one of " + METHODS.join(", "));
    }
    const lower = method.toLowerCase();
    if (METHODS.indexOf(lower) === -1) {
        throw typeError("the method must be one of " + METHODS.join(", "));
    }
    return lower;
}

function checkPath(path) {
    if (typeof path !== "string" && !(path instanceof RegExp)) {
        throw typeError("the path must be a string or a RegExp");
    }
}

/**
 * Flatten the handlers (arrays of any depth) into a new array of functions.
 * @return {Function[]}
 */
function flattenHandlers(handlers) {
    const result = [];
    const ancestors = [];
    function add(list) {
        if (ancestors.indexOf(list) !== -1) {
            throw typeError("an array of handlers contains itself");
        }
        ancestors.push(list);
        const length = list.length;
        for (let i = 0; i < length; i++) {
            const item = list[i];
            if (Array.isArray(item)) {
                add(item);
            } else if (typeof item === "function") {
                result.push(item);
            } else {
                throw typeError("every handler must be a function");
            }
        }
        ancestors.pop();
    }
    add(handlers);
    if (result.length === 0) {
        throw typeError("at least one handler function is required");
    }
    return result;
}

/**
 * The text of a thrown value for the log: its `message` when it is a string (at
 * most 200 characters), otherwise "unknown error".
 */
function messageOf(err) {
    try {
        const message = err.message;
        if (typeof message === "string") {
            return message.slice(0, MAX_MESSAGE_LENGTH);
        }
    } catch (readError) {
        // a value without a readable message (null, a hostile getter): the
        // fixed text below is logged instead
    }
    return UNKNOWN_ERROR;
}

function warn(node, key, params) {
    log.log({
        level: log.WARN,
        id: node.id,
        type: node.type,
        msg: log._(key, params)
    });
}

/**
 * Remove the layers of the given registrations from the current stacks of their
 * apps. A failure is logged once per call (without the paths or the methods) and
 * does not throw.
 * @param {object} node the node of the registrations (for the log)
 * @param {Array<{app, route}>} entries
 * @return {Array<{app, route}>} the entries of the apps whose removal failed (to
 *         try again later); empty when everything was removed
 */
function removeEntries(node, entries) {
    const byApp = new Map();
    entries.forEach(function(entry) {
        let routes = byApp.get(entry.app);
        if (!routes) {
            routes = new Set();
            byApp.set(entry.app, routes);
        }
        routes.add(entry.route);
    });
    let failure = null;
    const failedApps = new Set();
    byApp.forEach(function(routes, app) {
        try {
            const stack = routerStack(app);
            if (!stack) {
                return;
            }
            let left = routes.size;
            for (let i = stack.length - 1; i >= 0 && left > 0; i--) {
                const layer = stack[i];
                if (layer && routes.has(layer.route)) {
                    stack.splice(i, 1);
                    left--;
                }
            }
        } catch (err) {
            failedApps.add(app);
            if (!failure) {
                failure = { error: err };
            }
        }
    });
    if (!failure) {
        return [];
    }
    warn(node, "httpRoutes.remove-failed", { message: messageOf(failure.error) });
    return entries.filter(function(entry) { return failedApps.has(entry.app) });
}

function noop() {}

function createHandle(method, path, remove) {
    return Object.freeze({
        method: method,
        path: path,
        remove: remove
    });
}

/**
 * Register a route of a node on the app of the nodes.
 * The arguments are checked first (method, path, handlers); a failed
 * registration leaves the stack of the app unchanged.
 * @param {object} node the instance of the node
 * @param {string} method get, post, put, patch, delete, options, head or all (any case)
 * @param {string|RegExp} path passed to the app unchanged
 * @param {Array} handlers functions or arrays of them (any depth)
 * @return {{method: string, path: (string|RegExp), remove: Function}} a frozen handle
 * @throws {TypeError} invalid method, path or handlers
 * @throws {Error} no app of the nodes; an error of the app for the path is passed on
 */
function register(node, method, path, handlers) {
    const lowerMethod = checkMethod(method);
    checkPath(path);
    const list = flattenHandlers(handlers);

    let state = states.get(node);
    if (state && state.closed) {
        if (!state.warned) {
            state.warned = true;
            warn(node, "httpRoutes.after-close");
        }
        return createHandle(lowerMethod, path, noop);
    }
    const app = nodeApp;
    if (!app || typeof app.route !== "function") {
        throw new Error("registerHttpRoute: the runtime has no app for the HTTP routes of the nodes");
    }
    const route = app.route(path);
    route[lowerMethod](list);

    if (!state) {
        state = { closed: false, warned: false, routes: [] };
        states.set(node, state);
    }
    owners.set(route, node);
    const entry = { app: app, route: route };
    state.routes.push(entry);
    return createHandle(lowerMethod, path, function() {
        if (state.routes.indexOf(entry) === -1) {
            return;
        }
        // the entry stays tracked until its removal succeeds (a later close or
        // remove() tries again)
        if (removeEntries(node, [entry]).length === 0) {
            const index = state.routes.indexOf(entry);
            if (index !== -1) {
                state.routes.splice(index, 1);
            }
        }
    });
}

/**
 * Remove all routes of an instance of a node and mark it closed: a later
 * registration of the instance adds no route. Idempotent; never throws for a
 * failed removal (it is logged; the routes that were not removed stay tracked and
 * the next call tries again). For a node that never registered a route the first
 * call records one small state object (needed to ignore a later registration) and
 * later calls cost one lookup; the router is not read and nothing is logged.
 * @param {object} node the instance of the node
 */
function removeAll(node) {
    const state = states.get(node);
    if (state === undefined) {
        states.set(node, { closed: true, warned: false, routes: [] });
        return;
    }
    state.closed = true;
    if (state.routes.length === 0) {
        return;
    }
    state.routes = removeEntries(node, state.routes);
}

/**
 * The node that registered a route (#82, internal: the record of a drain 503).
 * The lookup is by identity, so nothing is read from the argument; the node is read
 * at the call and never its name.
 * @param {*} route the `Route` of the router (`req.route`)
 * @return {?{id: string, type: (string|undefined), z: (string|undefined)}} a new frozen
 *         object with `id` (a non-empty string), `type` when it is a string and `z` when
 *         it is a non-empty string; null for anything that is not a `Route` created by
 *         `register()` or when the node has no such id. Never throws
 */
function ownerOf(route) {
    // a WeakMap answers undefined for a primitive and calls no trap of a Proxy
    const node = owners.get(route);
    if (node === undefined) {
        return null;
    }
    try {
        const id = node.id;
        if (typeof id !== "string" || id === "") {
            return null;
        }
        const result = { id: id };
        const type = node.type;
        if (typeof type === "string") {
            result.type = type;
        }
        const z = node.z;
        if (typeof z === "string" && z !== "") {
            result.z = z;
        }
        return Object.freeze(result);
    } catch (err) {
        // a node whose properties cannot be read (a hostile getter) has no owner to report
        return null;
    }
}

module.exports = {
    init: init,
    register: register,
    removeAll: removeAll,
    ownerOf: ownerOf,
    routerStack: routerStack
};
